legacy_c2_ds.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffe_patches = image_patch.find("giraffe")
    if not giraffe_patches:
        return image_patch
    for patch in giraffe_patches:
        if patch.verify_property("giraffe", "tongue sticking out"):
            return patch
    return giraffe_patches[0]

